<script setup>
import { computed,onMounted,reactive,ref } from 'vue'
import { CircleOff,LoaderCircle,PartyPopper,RefreshCw,Siren,Timer } from 'lucide-vue-next'
import BaseModal from '../components/BaseModal.vue';import MetricCard from '../components/MetricCard.vue';import {showToast} from '../utils.js'
import {adminAuthState} from '../services/adminAuth.js';import {getGroupbuy,getGroupbuys,interveneGroupbuy} from '../services/groupbuy.js'
const rows=ref([]),total=ref(0),loading=ref(false),modal=ref(false),selected=ref(null),processing=ref(false),keyword=ref('');const filter=reactive({status:''});const form=reactive({action:'EXTEND',reason:'临近超时，延长等待时间',extendMinutes:30})
const shown=computed(()=>rows.value.filter(x=>`${x.activityId} ${x.couponName} ${x.merchantName}`.toLowerCase().includes(keyword.value.toLowerCase())))
const waiting=computed(()=>rows.value.filter(x=>['WAITING','SUSPEND'].includes(x.activityStatus)).length),success=computed(()=>rows.value.filter(x=>['SUCCESS','FORCE_SUCCESS'].includes(x.activityStatus)).length)
const metrics=computed(()=>[['进行中',String(waiting.value),'真实活动',Timer,false],['已成团',String(success.value),'自然/人工',PartyPopper,false],['待干预',String(rows.value.filter(x=>x.activityStatus==='WAITING'&&new Date(x.expireAt)-Date.now()<3600000).length),'一小时内到期',Siren,true],['总活动',String(total.value),'数据库记录',CircleOff,false]])
const label=s=>({WAITING:'等待拼单',SUCCESS:'拼单成功',TIMEOUT:'超时失败',CANCEL:'已关闭',FORCE_SUCCESS:'强制成功',FORCE_FAIL:'强制失败',SUSPEND:'已暂停'}[s]||s);const cls=s=>['SUCCESS','FORCE_SUCCESS'].includes(s)?'success':['TIMEOUT','CANCEL','FORCE_FAIL'].includes(s)?'danger':'warning'
async function load(){loading.value=true;try{const d=await getGroupbuys({status:filter.status});rows.value=d.records||[];total.value=Number(d.total||0)}catch(e){showToast(e.message)}finally{loading.value=false}}
async function open(row){selected.value=row;modal.value=true;try{selected.value=await getGroupbuy(row.activityId)}catch(e){showToast(e.message)}}
async function submit(){if(form.reason.trim().length<2)return showToast('请填写干预原因');processing.value=true;try{await interveneGroupbuy(selected.value.activityId,{action:form.action,reason:form.reason.trim(),operatorId:String(adminAuthState.operator?.operatorId||'10001'),extendMinutes:form.action==='EXTEND'?Number(form.extendMinutes):null,requestId:`GROUPBUY-${selected.value.activityId}-${Date.now()}`});showToast('干预已同步生效并记录审计日志');modal.value=false;await load()}catch(e){showToast(e.message)}finally{processing.value=false}}
onMounted(load)
</script>
<template><div class="page"><div class="page-head"><div><h1>拼单活动与人工干预</h1><p>真实监控拼单状态，支持成功、失败、延长、暂停与关闭。</p></div><button class="btn" @click="load"><LoaderCircle v-if="loading" class="spin"/><RefreshCw v-else/>刷新</button></div><div class="notice-box">干预动作同步写入 groupbuy_activity，并记录 admin_audit_log；不再展示静态原型数据。</div><div class="grid cols-4" style="margin-top:15px"><MetricCard v-for="m in metrics" :key="m[0]" :label="m[0]" :value="m[1]" :trend="m[2]" :icon="m[3]" :down="m[4]"/></div><section class="panel" style="margin-top:16px"><div class="toolbar"><input v-model="keyword" class="field search" placeholder="活动 ID / 优惠 / 商家"><select v-model="filter.status" class="field" @change="load"><option value="">全部状态</option><option>WAITING</option><option>SUCCESS</option><option>TIMEOUT</option><option>FORCE_SUCCESS</option><option>FORCE_FAIL</option><option>SUSPEND</option><option>CANCEL</option></select><span class="endpoint">GET /v1/admin/groupbuys</span></div><div v-if="!shown.length" class="empty-note"><Siren/><p>当前条件下没有拼单活动</p></div><div v-else class="table-wrap"><table><thead><tr><th>活动 / 优惠</th><th>商家 / 门店</th><th>成团进度</th><th>拼单价</th><th>截止时间</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="row in shown" :key="row.activityId"><td><b>{{row.couponName}}</b><small>{{row.activityId}}</small></td><td><b>{{row.merchantName}}</b><small>{{row.storeName||'—'}}</small></td><td>{{row.currentPeople}} / {{row.targetPeople}}<div class="progress"><span :style="{width:Math.min(100,row.currentPeople/row.targetPeople*100)+'%'}"></span></div></td><td>¥{{row.groupPrice}}</td><td>{{row.expireAt}}</td><td><span class="status" :class="cls(row.activityStatus)">{{label(row.activityStatus)}}</span></td><td><button class="btn sm" @click="open(row)">详情 / 干预</button></td></tr></tbody></table></div></section><BaseModal :open="modal" :title="`干预拼单 · ${selected?.activityId||''}`" @close="modal=false"><template v-if="selected"><div class="detail-grid"><div class="detail-item"><small>优惠券</small><b>{{selected.couponName}}</b></div><div class="detail-item"><small>当前进度</small><b>{{selected.currentPeople}} / {{selected.targetPeople}}</b></div><div class="detail-item"><small>状态</small><b>{{label(selected.activityStatus)}}</b></div><div class="detail-item"><small>截止时间</small><b>{{selected.expireAt}}</b></div></div><div class="form-grid" style="margin-top:14px"><div class="form-group"><label>干预动作</label><select v-model="form.action" class="field"><option value="FORCE_SUCCESS">强制成功</option><option value="FORCE_FAIL">强制失败</option><option value="EXTEND">延长时间</option><option value="SUSPEND">暂停拼单</option><option value="CLOSE">关闭拼单</option></select></div><div v-if="form.action==='EXTEND'" class="form-group"><label>延长分钟数</label><input v-model="form.extendMinutes" class="field" type="number" min="1" max="1440"></div><div class="form-group full"><label>干预原因</label><textarea v-model="form.reason" class="field" style="height:90px" maxlength="255"></textarea></div></div></template><template #footer><button class="btn" @click="modal=false">取消</button><button class="btn danger" :disabled="processing" @click="submit">{{processing?'办理中…':'确认干预'}}</button></template></BaseModal></div></template>
